const item = $input.first().json;
const stdout = item.stdout || "";
const stderr = item.stderr || "";
const exitCode = item.exitCode ?? 0;
const lines = stdout.split("\n").map(l => l.trim()).filter(Boolean);

return [{
  json: {
    tarea: "Sincronización Tracking Hover (Col H)",
    origen: "Ruteos (Col H)",
    destino: "Movimientos Unidades y Choferes",
    estado: exitCode === 0 ? "EXITOSO" : "FALLIDO",
    exitCode,
    resumen: lines.slice(-4).join(" | "),
    logCompleto: stdout,
    errores: stderr,
    ejecutadoEn: new Date().toISOString()
  }
}];

