const lines = stdout.split("\n").map(l => l.trim()).filter(Boolean);

const sinCambios = stdout.includes("GATEKEEPER") || stdout.includes("Sin cambios");
const fase2 = stdout.includes("FASE 2");

return [{
  json: {
    motor: "Polling Inteligente (Gatekeeper + Merge)",
    estado: exitCode === 0 ? "EXITOSO" : "FALLIDO",
    modo: sinCambios ? "FAST-GATE (Sin cambios, omitido)" : (fase2 ? "SYNC COMPLETO (Cambio detectado)" : "EJECUTADO"),
    exitCode,
    resumen: lines.slice(-5).join(" | "),
    logCompleto: stdout,
    errores: stderr,
    ejecutadoEn: new Date().toISOString()
  }
}];
